let detailDraft=null;const detailRequests=new Set();
const broadcastNames=I18n.labels({'Returning Series':'播出中','Ended':'已完结','Canceled':'已取消','In Production':'制作中','Planned':'未播出','Pilot':'试播','Released':'已上映','Post Production':'后期制作','Rumored':'未确认'});
const jobNames=I18n.labels({Director:'导演','Series Director':'系列导演','Creator':'原作 / 主创','Screenplay':'编剧','Writer':'编剧','Storyboard':'分镜','Storyboard Artist':'分镜','Original Music Composer':'音乐','Producer':'制片人','Executive Producer':'执行制片人','Character Designer':'角色设计','Animation Director':'作画监督','Art Direction':'美术指导'});
function safeSite(url){return typeof url==='string'&&/^https?:\/\//i.test(url)?url:''}
function normalizeWatchURL(value){const raw=String(value||'').trim();if(!raw||/[\s\u0000-\u001f]/.test(raw))return '';try{const url=new URL(/^[a-z][a-z0-9+.-]*:/i.test(raw)?raw:'https://'+raw);return ['https:','http:'].includes(url.protocol)&&url.hostname.includes('.')&&!url.username&&!url.password?url.href:'';}catch{return '';}}
function watchSiteAction(a){const url=normalizeWatchURL(a.watchSite?.url),name=String(a.watchSite?.name||'').trim();if(!url||!name)return '<button class="detail-action" id="configureWatchSite">▷<span>'+t('设置观看站点')+'</span></button>';const label=I18n.getLanguage()==='en-US'?'Watch with '+name:'在 '+name+' 观看';return '<a class="detail-action" id="watchLink" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer" title="'+esc(label)+'">▷<span>'+esc(label)+'</span></a>';}
function personRail(list,staff=false){if(!Array.isArray(list)||!list.length)return t("<p class=\"detail-empty\">暂无资料</p>");return '<div class="people-rail">'+list.filter(p=>p&&typeof p.name==='string').map(p=>ui`<article class="person-tile">${p.image?ui`<img src="${esc(safeImage(p.image))}" alt="${esc(p.name)}" loading="lazy">`:ui`<div class="person-placeholder" aria-label="暂无照片">${esc(p.name.slice(0,1))}</div>`}<div><strong>${esc(p.name)}</strong><span>${esc(staff?String(p.role||'').split(' / ').map(r=>jobNames[r]||r).join(' / '):p.role||t("演员"))}</span></div></article>`).join('')+'</div>'}
function detailSection(title,content,id=''){return ui`<section class="detail-section" ${id?ui`id="${id}"`:''}><h3>${title}</h3>${content}</section>`}
function seasonMarkup(a){
 if(Array.isArray(a.seasonEntries))return '<p class="detail-empty">'+(I18n.getLanguage()==='en-US'?'Open a season record below to view its episodes.':'请在下方打开季度记录查看分集资料。')+'</p>';
 if(a.tmdbType==='movie')return t('<p class="detail-empty">电影无分集资料</p>');
 const seasons=Array.isArray(a.seasons)?a.seasons.filter(s=>s&&Number.isInteger(s.number)&&s.number>=0&&s.number<=999):[];
 if(!seasons.length)return t('<p class="detail-empty">暂无分季资料</p>');
 return seasons.map(s=>ui`<details class="episode-season" data-season="${s.number}"><summary>${s.number===0?t("特别篇"):(I18n.getLanguage()==='en-US'?ui`Season ${s.number}`:ui`第 ${s.number} 季`)}<span>${esc(s.episodes)} 集</span></summary><div class="season-content" id="seasonContent${s.number}">${a.episodeDetails?.[s.number]&&((a.episodeLanguages?.[s.number]||'zh-CN')===I18n.getLanguage()||!tmdbCredential)?episodeMarkup(a.episodeDetails[s.number]):'<button class="load-season" data-load-season="'+s.number+t('">加载分集资料</button>')}</div></details>`).join('');
}
function detailRuntime(value){return typeof value==='number'&&Number.isFinite(value)&&value>0&&value<=1440?String(value):''}
function episodeMarkup(episodes){if(!Array.isArray(episodes)||!episodes.length)return t("<p class=\"detail-empty\">暂无分集资料</p>");return episodes.filter(e=>e&&Number.isInteger(e.number)&&e.number>=0&&e.number<=9999).map(e=>ui`<article class="episode-row">${e.image?ui`<img src="${esc(safeImage(e.image))}" alt="${I18n.getLanguage()==='en-US'?ui`Episode ${e.number} thumbnail`:ui`第 ${e.number} 集缩略图`}" loading="lazy">`:t("<div class=\"episode-placeholder\">暂无图片</div>")}<div><h4>${e.number}. ${esc(e.name||t("未命名"))}</h4><small>${esc(e.airDate?I18n.formatDate(e.airDate):t("播出日期未知"))}${detailRuntime(e.runtime)?ui` · ${detailRuntime(e.runtime)} 分钟`:''}</small><p>${esc(e.overview||t("暂无简介"))}</p></div></article>`).join('')}
function renderDetail(a){const d=detailDraft,site=safeSite(a.homepage),date=a.airDate?I18n.formatDate(a.airDate):t("开播时间未知"),status=broadcastNames[a.broadcastStatus]||a.broadcastStatus||t("播出情况未知"),season=a.tmdbType==='movie'?t("电影"):Array.isArray(a.seasonEntries)?ui`${a.seasonEntries.length} 季（已合并）`:Number.isInteger(a.seasonNumber)?SeasonModel.label(a.seasonNumber):a.seasonCount!=null?ui`${a.seasonCount} 季`:t("季度未知");
 $('#detailBody').innerHTML=ui`<div class="detail-cover">${a.heroImage||a.image?ui`<img class="detail-cover-art" src="${esc(safeImage(a.heroImage||a.image))}" alt="${esc(a.title)}海报">`:'<div class="detail-cover-placeholder"></div>'}<div class="detail-cover-fade"></div><div class="detail-title-area">${a.titleLogo?ui`<img class="detail-title-logo" src="${esc(safeImage(a.titleLogo))}" alt="${esc(a.title)}"><h2 class="detail-title-fallback" hidden>${esc(a.title)}</h2>`:ui`<h2 class="detail-title-fallback">${esc(a.title)}</h2>`}${Number.isInteger(a.seasonNumber)?ui`<p class="detail-season-title">${esc(a.title)}</p>`:''}<p class="detail-air-meta">${esc(date)}<span>·</span>${esc(status)}<span>·</span>${esc(season)}</p><p class="detail-genres">${esc(a.genre||t("未分类"))}</p></div></div>
 <div class="detail-content"><div class="detail-actions">${watchSiteAction(a)}${site?ui`<a href="${esc(site)}" target="_blank" rel="noopener" class="detail-action">↗<span>官方网站</span></a>`:t("<button class=\"detail-action\" disabled title=\"暂无官方网站\">↗<span>官方网站</span></button>")}<button class="detail-action ${a.favorite?'is-favorite':''}" id="favorite" aria-pressed="${!!a.favorite}">♡<span>${a.favorite?t("已收藏"):t("收藏")}</span></button><button class="detail-action danger" id="deleteAnime">×<span>删除动漫</span></button></div>
 <div class="watch-site-settings"><button id="editWatchSite">${t(a.watchSite?'编辑观看站点':'添加观看站点')}</button></div><form id="watchSiteEditor" class="watch-site-editor" hidden><label for="watchSiteName">站点名称<input id="watchSiteName" maxlength="60" required value="${esc(a.watchSite?.name||'')}" placeholder="例如：Bilibili"></label><label for="watchSiteURL">观看网址<input id="watchSiteURL" type="text" inputmode="url" spellcheck="false" required value="${esc(a.watchSite?.url||'')}" placeholder="https://www.bilibili.com/..."></label><div class="watch-site-editor-actions"><button type="submit">保存观看站点</button><button id="cancelWatchSite" type="button">取消</button><button id="removeWatchSite" type="button" ${a.watchSite?'':'hidden'}>移除观看站点</button></div><p id="watchSiteError" role="status"></p></form><div class="detail-metrics"><div><span>★</span><strong>${a.tmdbVoteCount===0||!a.tmdbRating?'—':Number(a.tmdbRating).toFixed(1)}</strong><small>${a.scoreScope==='season'?t('TMDb 季度分数'):t('TMDb 分数')}</small></div><div><span>▷</span><strong>${a.episodeCountUnknown?'—':a.episodes}</strong><small>总集数</small></div><div><span>◷</span><strong>${detailRuntime(a.runtime)?ui`${detailRuntime(a.runtime)}<em>分钟</em>`:'—'}</strong><small>每集时间</small></div></div>
 ${detailSection(t("自己评分"),ui`<div class="personal-rating"><div id="ratingStars" class="rating-stars" aria-label="个人评分"></div><span id="ratingValue"></span><button id="clearRating">清除</button></div>`)}
 ${detailSection(t("观看追踪")+ui` <button type="button" id="rewatchToggle" class="rewatch-toggle" aria-label="重看次数" aria-expanded="false" aria-controls="rewatchEditor">↻ × ${esc(d.rewatchCount)}</button>`,ui`<div id="rewatchEditor" class="rewatch-editor" hidden><label for="rewatchCount">重看次数<input id="rewatchCount" type="number" min="0" max="999" step="1" value="${esc(d.rewatchCount)}"></label><p>0 为首次观看；1 为第一轮重看。增加次数时开始新一轮，统计包含此前完整观看。</p></div><div class="tracking-status" id="trackingStatus">${Object.entries(statuses).map(([k,v])=>ui`<button data-status="${k}" class="${d.status===k?'selected':''}" aria-pressed="${d.status===k}">${v}</button>`).join('')}</div><div class="episode-controls"><button id="minusEpisode" aria-label="减少一集">−</button><label>已看<input id="episodeValue" type="number" min="0" max="${esc(a.episodes)}" value="${esc(d.progress)}" aria-label="已看集数"> / ${esc(a.episodes)} 集</label><button id="plusEpisode" aria-label="增加一集">+</button></div><div class="tracking-dates"><label>开始日期<input id="detailStartDate" type="date" value="${esc(d.startDate)}"></label><label>完成日期<input id="detailFinishDate" type="date" value="${esc(d.finishDate)}"></label></div><label class="detail-note-label">笔记<textarea id="detailNote" maxlength="${Math.max(2000,String(d.note||'').length+2000)}" placeholder="输入观看笔记">${esc(d.note)}</textarea></label><fieldset class="watch-days"><legend>每周观看日</legend><div id="detailWatchDays" class="watch-days-options">${WatchSchedule.checkboxes(d.watchDays)}</div></fieldset><button id="saveDetail" class="primary">保存观看记录</button>`,'detailTracking')}
 ${detailSection(t("概览"),ui`<p class="detail-overview">${esc(a.overview||t("暂无概要"))}</p>`)}
 ${detailSection(t("主演"),personRail(a.cast))}${detailSection(t("工作人员"),personRail(a.crew,true))}${detailSection(t("每集简介"),seasonMarkup(a))}
 ${a.tmdbId?ui`<div class="detail-source"><a href="https://www.themoviedb.org/${a.tmdbType==='movie'?'movie':'tv'}/${Number(a.tmdbId)}${Number.isInteger(a.seasonNumber)?'/season/'+a.seasonNumber:''}" target="_blank" rel="noopener">TMDb 资料 ↗</a><button id="refreshDetails">更新资料</button><span id="detailLoadStatus" role="status"></span></div>`:''}</div>`;
 $('#deleteAnime').onclick=()=>deleteAnime(a.id);$('#favorite').onclick=()=>{a.favorite=!a.favorite;save();const b=$('#favorite');b.setAttribute('aria-pressed',String(!!a.favorite));b.classList.toggle('is-favorite',!!a.favorite);b.innerHTML='♡<span>'+(a.favorite?t("已收藏"):t("收藏"))+'</span>'};
 const openWatchSiteEditor=()=>{$('#watchSiteEditor').hidden=false;$('#watchSiteName').focus();};$('#editWatchSite').onclick=openWatchSiteEditor;if(!normalizeWatchURL(a.watchSite?.url)||!a.watchSite?.name)$('#configureWatchSite').onclick=openWatchSiteEditor;
 $('#cancelWatchSite').onclick=()=>{$('#watchSiteEditor').hidden=true;$('#editWatchSite').focus();};
 const persistWatchSite=site=>{const next=patchLibraryEntry(a.id,{watchSite:site});const current=findLibraryEntry(a.id);if(!current)throw Error();AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));current.watchSite=site;library=next;if(current!==a)Object.assign(a,current);renderDetail(findLibraryEntry(a.id));$('#editWatchSite').focus();toast(t('观看站点已保存'));};
 $('#watchSiteEditor').onsubmit=e=>{e.preventDefault();const name=$('#watchSiteName').value.trim(),url=normalizeWatchURL($('#watchSiteURL').value);if(!name||name.length>60||!url){$('#watchSiteError').textContent=t('请输入站点名称和有效的 HTTP / HTTPS 网址');return;}try{persistWatchSite({name,url});}catch{$('#watchSiteError').textContent=t('保存失败，请检查存储空间');}};
 $('#removeWatchSite').onclick=()=>{try{persistWatchSite(null);}catch{$('#watchSiteError').textContent=t('保存失败，请检查存储空间');}};
 $('#clearRating').onclick=()=>{d.rating=0;renderStars()};renderStars();
 const today=()=>new Date().toLocaleDateString('sv-SE');
 const syncTracking=()=>{$('#rewatchToggle').textContent='↻ × '+d.rewatchCount;$('#rewatchCount').value=d.rewatchCount;$$('#trackingStatus button').forEach(btn=>{const selected=btn.dataset.status===d.status;btn.classList.toggle('selected',selected);btn.setAttribute('aria-pressed',String(selected));});};
 const setRewatchCount=count=>{if(!Number.isInteger(count)||count<0||count>999){$('#rewatchCount').value=d.rewatchCount;toast(t('重看次数须为 0 到 999 的整数'));return;}const increase=count>d.rewatchCount;d.rewatchCount=count;if(increase){d.progress=0;$('#episodeValue').value=0;d.startDate=today();d.finishDate='';$('#detailStartDate').value=d.startDate;$('#detailFinishDate').value='';}if(['watching','rewatching','completed'].includes(d.status))d.status=count?'rewatching':'watching';syncTracking();};
 $('#rewatchToggle').onclick=()=>{const editor=$('#rewatchEditor');editor.hidden=!editor.hidden;$('#rewatchToggle').setAttribute('aria-expanded',String(!editor.hidden));if(!editor.hidden)$('#rewatchCount').focus();};$('#rewatchCount').onchange=()=>setRewatchCount(Number($('#rewatchCount').value));
 $$('#trackingStatus button').forEach(b=>b.onclick=()=>{const next=b.dataset.status;if(next==='rewatching'){if(!d.rewatchCount||(d.status==='completed'&&d.progress>=a.episodes)){d.status='rewatching';setRewatchCount(d.rewatchCount+1);}d.status='rewatching';}else{d.status=next;if(next==='watching'){d.rewatchCount=0;syncTracking();}}if(['watching','rewatching'].includes(d.status)&&!d.startDate){d.startDate=today();$('#detailStartDate').value=d.startDate;}if(d.status==='completed'){d.progress=a.episodes;$('#episodeValue').value=d.progress;if(!d.finishDate){d.finishDate=today();$('#detailFinishDate').value=d.finishDate;}}syncTracking();});
 $('#minusEpisode').onclick=()=>{d.progress=Math.max(0,(Number($('#episodeValue').value)||0)-1);$('#episodeValue').value=d.progress};$('#plusEpisode').onclick=()=>{d.progress=Math.min(a.episodes,(Number($('#episodeValue').value)||0)+1);$('#episodeValue').value=d.progress};$('#episodeValue').oninput=()=>d.progress=Number($('#episodeValue').value);$('#detailNote').oninput=()=>d.note=$('#detailNote').value;$('#detailStartDate').onchange=()=>d.startDate=$('#detailStartDate').value;$('#detailFinishDate').onchange=()=>d.finishDate=$('#detailFinishDate').value;$$('#detailWatchDays input').forEach(input=>input.onchange=()=>{d.watchDays=WatchSchedule.normalizeDays($$('#detailWatchDays input').filter(el=>el.checked).map(el=>Number(el.value)))});
 $('#saveDetail').onclick=()=>{const progress=Number($('#episodeValue').value);if(!Number.isInteger(progress)||progress<0||progress>a.episodes){toast(t("集数须在 0 到 ")+a.episodes+t(" 之间"));return}d.startDate=$('#detailStartDate').value;d.finishDate=$('#detailFinishDate').value;if(d.startDate&&d.finishDate&&d.finishDate<d.startDate){toast(t("完成日期不能早于开始日期"));return}const changes={rating:d.rating,rewatchCount:d.rewatchCount,status:d.status==='rewatching'&&!d.rewatchCount?'watching':d.status,note:$('#detailNote').value,startDate:d.startDate,finishDate:d.finishDate,progress:d.status==='completed'?a.episodes:progress,watchDay:null,watchDays:WatchSchedule.normalizeDays(d.watchDays)};if(changes.progress===a.episodes&&['watching','rewatching'].includes(changes.status))changes.status='completed';const next=patchLibraryEntry(a.id,changes);try{WatchHistory.commit(next,a,changes);library=next;Object.assign(a,changes);detailDraft={...detailDraft,...changes};render();if(selectedId===a.id&&$('#detailDialog').open)renderDetail(findLibraryEntry(a.id));toast(t("观看记录已保存"))}catch{toast(t("保存失败，请检查存储空间"))}};
 if(a.tmdbId)$('#refreshDetails').onclick=()=>loadDetailMetadata(a,true);
 $$('[data-load-season]').forEach(b=>b.onclick=()=>loadSeason(a,Number(b.dataset.loadSeason)));
 $$('.episode-season').forEach(el=>el.addEventListener('toggle',()=>{const number=Number(el.dataset.season);if(el.open&&(!a.episodeDetails?.[number]||(a.episodeLanguages?.[number]||'zh-CN')!==I18n.getLanguage()))loadSeason(a,number)}));
 $$('#detailBody img').forEach(img=>img.onerror=()=>{img.onerror=null;if(img.classList.contains('detail-title-logo')){img.hidden=true;$('#detailBody .detail-title-fallback').hidden=false}else img.src=placeholder});
}
function renderStars(){if(!detailDraft)return;const score=Number(detailDraft.rating)||0;const starIcon='<svg class="rating-star-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2 15.1 8.4 22.2 9.4 17.1 14.4 18.3 21.5 12 18.2 5.7 21.5 6.9 14.4 1.8 9.4 8.9 8.4Z"/></svg>';$('#ratingStars').innerHTML=Array.from({length:5},(_,i)=>ui`<button class="rating-star" data-star="${i+1}" aria-label="${i+1} 星，${(i+1)*2} 分"><span class="rating-star-shape" aria-hidden="true">${starIcon}<span class="filled-star" style="width:${Math.max(0,Math.min(1,score/2-i))*100}%">${starIcon}</span></span></button>`).join('');$('#ratingValue').textContent=score?ui`${score.toFixed(1)} / 10`:t("未评分");$$('#ratingStars button').forEach(b=>{b.onclick=e=>{const n=Number(b.dataset.star);const half=e.detail!==0&&e.clientX-b.getBoundingClientRect().left<b.getBoundingClientRect().width/2;detailDraft.rating=n*2-(half?1:0);renderStars()};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();detailDraft.rating=Math.max(0,Math.min(10,detailDraft.rating+(e.key==='ArrowRight'?1:-1)));renderStars();$$('#ratingStars button')[Number(b.dataset.star)-1]?.focus()}}})}
openDetail=function(id){const a=findLibraryEntry(id);if(!a)return;selectedId=id;detailDraft={id,rewatchCount:WatchHistory.cycle(a),status:a.status,progress:a.progress,rating:a.rating,note:a.note||'',startDate:a.startDate||'',finishDate:a.finishDate||'',watchDays:WatchSchedule.recordDays(a)};renderDetail(a);showDetailPanel();if(a.tmdbId&&(!a.detailsVersion||a.detailsVersion<2||(a.metadataLanguage||'zh-CN')!==I18n.getLanguage())&&tmdbCredential)loadDetailMetadata(a)};
async function loadDetailMetadata(a,force=false){if(!tmdbCredential){toast(t("请先在设置中配置 TMDb"));return}const key='detail-'+a.id;if(detailRequests.has(key))return;detailRequests.add(key);if(selectedId===a.id)$('#detailLoadStatus').textContent=t("加载中…");try{const data=await TMDB.request(a.tmdbType+'/'+a.tmdbId,tmdbCredential,{append_to_response:a.tmdbType==='movie'?'images,credits':'images,aggregate_credits',include_image_language:'zh,ja,en,null'});if(!findLibraryEntry(a.id))return;Object.assign(a,TMDB.metadata(data,a.tmdbType));a.title=String(data.name||data.title||a.title).slice(0,100);a.en=data.original_name||data.original_title||a.en;render();if(!a.overview&&data.overview)a.overview=data.overview;AppStorage.setItem('anishelf-library-v1',JSON.stringify(library));if(selectedId===a.id&&$('#detailDialog').open){renderDetail(a);$('#detailLoadStatus').textContent=t("已更新")}}catch(error){if(selectedId===a.id&&$('#detailDialog').open)$('#detailLoadStatus').textContent=error.message}finally{detailRequests.delete(key)}}
async function loadSeason(a,number){const key='season-'+a.id+'-'+number;if(detailRequests.has(key))return;const target='#seasonContent'+number;if(a.episodeDetails?.[number]&&((a.episodeLanguages?.[number]||'zh-CN')===I18n.getLanguage()||!tmdbCredential)){if(selectedId===a.id)$(target).innerHTML=episodeMarkup(a.episodeDetails[number]);return}if(!tmdbCredential){if(selectedId===a.id)$(target).innerHTML=t("<p class=\"detail-empty\">请在设置中配置 TMDb 后加载</p>");return}detailRequests.add(key);if(selectedId===a.id)$(target).innerHTML=t("<p class=\"detail-empty\">加载中…</p>");try{const data=await TMDB.request('tv/'+a.tmdbId+'/season/'+number,tmdbCredential);if(!findLibraryEntry(a.id))return;const episodes=(data.episodes||[]).map(e=>({number:e.episode_number,name:e.name||'',overview:e.overview||'',airDate:e.air_date||'',runtime:e.runtime||null,image:TMDB.imageUrl(e.still_path,'w342')}));a.episodeDetails={...a.episodeDetails,[number]:episodes};a.episodeLanguages={...a.episodeLanguages,[number]:I18n.getLanguage()};AppStorage.setItem('anishelf-library-v1',JSON.stringify(library));if(selectedId===a.id&&$('#detailDialog').open){$(target).innerHTML=episodeMarkup(episodes);$$(target+' img').forEach(img=>img.onerror=()=>{img.onerror=null;img.src=placeholder})}}catch(error){if(selectedId===a.id&&$('#detailDialog').open){$(target).innerHTML='<p class="detail-empty">'+esc(error.message)+t("</p><button class=\"load-season\" id=\"retrySeason\">重试</button>");$('#retrySeason').onclick=()=>loadSeason(a,number)}}finally{detailRequests.delete(key)}}
